/* #229 debug: read the active host CR3 (which page-table root this core runs under). */
static inline uint64_t hype_dbg_read_cr3(void) {
    uint64_t v;
    __asm__ volatile("mov %%cr3, %0" : "=r"(v));
    return v;
}
