/*
 * SVM-only diagnostics. Each returns 0 on VMX so the caller skips the print
 * entirely rather than reporting fabricated zeros.
 *
 * These are deliberately NOT ported. hype_svm_debug_state_t is an SVM
 * investigation artifact -- EXITINFO2, EXITINTINFO, NRIP, G_PAT are VMCB fields
 * with no VMCS counterpart, and several exist specifically to answer questions
 * about AMD save-area behaviour. Likewise the EVENTINJ-collision and MTRR
 * counters are file-scope tallies inside svm_vcpu.c. Porting an SVM debugging
 * apparatus is not what Intel parity requires; running a guest is.
 */
/*
 * #249: the SVM-named struct in a vendor-neutral shim is deliberate, not an
 * oversight. It IS the SVM snapshot -- EXITINFO2 / EXITINTINFO / NRIP / G_PAT have
 * no VMCS counterpart -- so there is no neutral type to promote it to. The shim
 * exists to answer "is that snapshot available?", and returns 0 on VMX.
 */
static int vmm_get_debug_state(hype_vmm_kind_t kind, hype_vcpu_ctx_t *ctx,
                               hype_svm_debug_state_t *out) {
    if (kind == HYPE_VMM_KIND_VMX) {
        /*
         * ZERO the struct rather than leaving it untouched, even though the
         * return value already says "nothing here". Callers declare it on the
         * stack and several read fields without checking the return -- so on
         * VMX they were reading uninitialised stack, and two of them fed
         * .cr3/.rip straight into a guest page-table walk, i.e. dereferencing
         * through a garbage root. Zeroing makes that deterministic and inert
         * instead of wild. Check the return value if you need to know whether
         * the contents mean anything; zeros are not a valid guest state.
         *
         * Field-by-field, not `*out = (hype_svm_debug_state_t){0}` -- this is a
         * freestanding UEFI target with no libc, and aggregate assignment emits
         * a call to memcpy/memset that fails at link time (see AGENTS.md).
         */
        out->cs_selector = 0;
        out->cs_base = 0;
        out->cr0 = 0;
        out->cr2 = 0;
        out->cr3 = 0;
        out->rip = 0;
        out->rflags = 0;
        out->rsp = 0;
        out->exitinfo2 = 0;
        out->exitintinfo = 0;
        out->nrip = 0;
        out->cr4 = 0;
        out->g_pat = 0;
        return 0;
    }
    hype_svm_vcpu_get_debug_state(ctx, out);
    return 1;
}
static int vmm_get_int_diag(hype_vmm_kind_t kind, unsigned long long *eventinj,
                            unsigned long long *defer, unsigned long long *window,
                            unsigned long long *overwrite) {
    if (kind == HYPE_VMM_KIND_VMX) {
        hype_vmx_vcpu_get_int_diag(eventinj, defer, window, overwrite);
        return 1;
    }
    hype_svm_vcpu_get_int_diag(eventinj, defer, window, overwrite);
    return 1;
}
